DELIMITER $$
CREATE TRIGGER tr_sc_insert BEFORE INSERT ON SC
FOR EACH ROW
BEGIN
  IF NEW.Grade < 0 THEN
    SET NEW.Grade = 0;
  ELSEIF NEW.Grade > 100 THEN
    SET NEW.Grade = 100;
  END IF;
END $$
DELIMITER ;

CREATE USER 'wang'@'localhost' IDENTIFIED BY 'abc123';
GRANT SELECT, INSERT ON db_school.S
  TO 'wang'@'localhost' WITH GRANT OPTION;
GRANT UPDATE(Grade) ON db_school.SC TO 'wang'@'localhost';
REVOKE INSERT ON db_school.S FROM 'wang'@'localhost';
